extracted_python_code:
faang_tickers = ('AMZN', 'AAPL', 'GOOGL', 'META', 'NFLX')

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (ENDSWITH(email, '.com')) & 
            (HAS(transactions_made.WHERE(ISIN(ticker.symbol, faang_tickers))) == 1)
        )
    )
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "Active")
).PARTITION(name="country_group", by=country).CALCULATE(
    country=country,
    TAC=COUNT(Customers)
)

result = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).PARTITION(name="country_group", by=(country)).CALCULATE(
    country=country,
    AR = 100.0 * COUNT(Customers.WHERE(status == 'active')) / COUNT(Customers)
)

result = Broker.CALCULATE(
    num_customers=COUNT(Customers.WHERE(
        (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) & 
        ENDSWITH(LOWER(state), 'a')
    ))
)

top_stocks_by_price_change = DailyPrices.WHERE(
    (date >= "2023-04-01") & (date <= "2023-04-04")
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_prices", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    price_change=MAX(DailyPrices.high) - MIN(DailyPrices.low)
).TOP_K(3, by=price_change.DESC())

distinct_customer_ids = Transactions.WHERE(
    transaction_type == 'buy'
).PARTITION(
    name="customers", by=(customer_id)
).CALCULATE(
    customer_id=customer_id
)

distinct_ticker_ids_after_date = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="distinct_tickers", by=(ticker_id)).CALCULATE(
    ticker_id=ticker_id
)

lowest_price_vti = Broker.CALCULATE(
    lowest_daily_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & (DATEDIFF("days", date, 'now') <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME('now')) <= 70
        ).transactions_made
    )
)

successful_transactions_q1_2023 = Transactions.WHERE(
    (status == 'success') &
    (YEAR(date_time) == 2023) &
    (MONTH(date_time) <= 3)
).CALCULATE(
    transaction_month=MONTH(date_time)
)

monthly_average_price = successful_transactions_q1_2023.PARTITION(
    name="monthly_transactions", by=(transaction_month)
).CALCULATE(
    month=transaction_month,
    average_transaction_price=AVG(Transactions.price)
).ORDER_BY(transaction_month.ASC())

result = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

result = Dealership.CALCULATE(
    average_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_to_pay=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_to_pay
        ),
        2
    )
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

salespersons_with_cash_payments = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Drugs.WHERE(
    HAS(treatments_used_in.WHERE(~(end_dt == None))) == 1
).CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            ~(end_dt == None)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            (ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com"))
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == "Psoriasis vulgaris") & 
                    (drug.drug_type == "Biologic")
                )
            ) == 1
        )
    )
)

alice_treatments_in_last_6_months = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(first_name == "Alice").treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) & 
            (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

monthly_diagnoses_and_treatments = Treatments.CALCULATE(
    treatment_month=DATETIME(start_dt, 'start of month')
).WHERE(
    (treatment_month >= DATETIME('now', 'start of month', '-12 months')) &
    (treatment_month < DATETIME('now', 'start of month'))
).PARTITION(
    name="monthly_treatments", by=(treatment_month)
).CALCULATE(
    month=treatment_month,
    PMPD=NDISTINCT(Treatments.patient_id),
    PMTC=COUNT(Treatments)
).ORDER_BY(treatment_month.ASC())

result = DermTreatment.CALCULATE(
    average_weight=AVG(Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg)
)

male_patient_caw = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

private_insured_female_patients = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == 'female') & (ins_type == 'private')))
)

top_drug_by_adverse_events = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) & 
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == "Biologic")) == 1
).PARTITION(name="states", by=(loc_state,)).CALCULATE(
    state=loc_state
)

insurance_type_performance = Treatments.WHERE(
    YEAR(end_dt) == 2022
).CALCULATE(
    insurance_type=patient.ins_type
).PARTITION(
    name="insurance_groups", by=insurance_type
).CALCULATE(
    ins_type=insurance_type,
    avg_pasi_score=AVG(Treatments.outcome_records.day100_pasi_score),
    num_distinct_patients=NDISTINCT(Treatments.patient.patient_id)
).TOP_K(
    5, by=avg_pasi_score.ASC()
)

top_specialties_by_drug_amount = Treatments.WHERE(
    DATEDIFF("months", start_dt, DATETIME('now')) < 6
).CALCULATE(
    speciality=doctor.speciality
).PARTITION(
    name="specialty_groups", by=(speciality)
).CALCULATE(
    speciality=speciality,
    number_of_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(3, by=total_drug_amount.DESC())

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            LIKE(LOWER(diagnosis.diag_name), '%psoriasis%') &
            (HAS(drug.fda_appr_dt) == 1) &
            (DATEDIFF("days", end_dt, DATETIME('now')) <= 180)
        )
    )
)

first_treatment_by_recent_doctors = Doctors.WHERE(
    year_reg == YEAR(DATETIME('now')) - 2
).prescribed_treatments.WHERE(
    RANKING(by=start_dt.ASC(), per="Doctors") == 1
).CALCULATE(
    last_name=doctor.last_name,
    year_reg=doctor.year_reg,
    first_treatment_id=treatment_id,
    first_treatment_date=start_dt
)

avg_patient_age = DermTreatment.CALCULATE(
    avg_age=ROUND(AVG(
        Patients.WHERE(
            (gender == 'male') & (ins_type == 'private')
        ).CALCULATE(
            age_in_years=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age_in_years
    ), 0)
)

user_session_duration_analysis = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration
    )
).WHERE(
    total_duration > 0
).ORDER_BY(
    total_duration.DESC()
)

tuc_past_month = Ewallet.CALCULATE(
    TUC=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

result = Merchants.CALCULATE(
    merchant_creation_year=YEAR(created_at),
    merchant_creation_month=MONTH(created_at)
).CALCULATE(
    mid=mid,
    name=name,
    num_coupons=COUNT(coupons.WHERE(
        (YEAR(created_at) == merchant_creation_year) & (MONTH(created_at) == merchant_creation_month)
    ))
).TOP_K(1, by=num_coupons.DESC())

distinct_merchant_receivers = Transactions.WHERE(receiver_type == 1).PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

distinct_users_with_transaction_notifications = Notifications.WHERE(notification_type == 'TRANSACTION').PARTITION(name="distinct_users", by=(user_id)).CALCULATE(
    user_id=user_id
)

median_balance_result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (status == 'active') & (CONTAINS(category, 'retail'))
        ).balances.WHERE(
            DATEDIFF("days", updated_at, DATETIME('now')) == 0
        ).balance
    )
)
